const cce_t2_uni = [11]u32{ 12288, 12352, 12448, 19968, 13312, 44032, 3584, 8192, 127744, 9728, 9984 };
const cce_t2_size = [11]u32{ 64, 96, 96, 20992, 6592, 11172, 256, 512, 1024, 256, 192 };
fn cx_cce_to_cp(c: i64) i64 {
