    for (cce_t1_code, cce_t1_size, cce_t1_uni) |start, size, uni| {
        if (u >= uni and u < uni + size) return @intCast(start + (u - uni));
    }
    var base: u32 = 2176;
    for (cce_t2_uni, cce_t2_size) |uni, size| {
        if (u >= uni and u < uni + size) return @intCast(base + (u - uni));
        base += size;
    }
